let produit = 'Livre';
let prix = 19.99;
let quantite = 3;
let total = prix * quantite;
console.log('Produit : ' + produit);
console.log('Total : ' + total + ' euros');

const rayon = 5;
const PI = 3.14159;
let aire = PI * rayon * rayon;
console.log('Aire : ' + aire);

let message = 'Globalement';

function afficherMessage() {
  let message = 'Localement';
  console.log(message);
}

afficherMessage();  // Affiche: Localement
console.log(message);  // Affiche: Globalement

const tauxTVA = 0.20;
let prixHT = 100;
let prixTTC = prixHT * (1 + tauxTVA);

console.log('Prix HT : ' + prixHT);
console.log('Taux TVA : ' + tauxTVA * 100 + '%');
console.log('Prix TTC : ' + prixTTC);
